D[32897]={"^Increases Shadow damage dealt by (.-)%% and Shadow spell critical strike chance by (.-)%%%. Lasts (.-)%.%s*$","Aumenta o dano de Sombra causado em {{1}}% e a chance de acerto crítico com feitiços de Sombras em {{2}}%. Dura {{3}}."}
D[32898]={"^Dummy effect to proc only on 3 stacks of 980049%.%s*$","Efeito simulacro para ativar somente com 3 acúmulos de 980049."}
D[32899]={"^Increases physical damage done by (.-)%% and addtionally Sinister Strike damage by (.-)%%%. Lasts (.-)%. Stacks up to 3%.%s*$","Aumenta o dano Físico causado em {{1}}% e além o dano de Golpe Sinistro em {{2}}%. Dura {{3}}. Acumula até 3."}
D[32900]={"^Increases Shadow critical strike chance by (.-)%%%.%s*$","Aumenta a chance de acerto crítico em {{1}}% com Sombras em."}
